import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, smoothstep, vec3, vec2, fract, dot, sin, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'home-hero-headline';
  const inner = new Group();
  group.add(inner);

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const timelines = [];
  const disposables = [];

  const uSurface = uniform(new Color(surfaceHex));
  const uInk = uniform(new Color(inkHex));
  const uAccent = uniform(new Color(accentHex));

  // --- Backdrop: engineered gradient + subtle grain ---
  const backdropGeo = new PlaneGeometry(7, 3);
  disposables.push(backdropGeo);

  const gradY = uv().y;
  const baseColor = mix(uSurface, uInk, smoothstep(0, 1, gradY));
  const accentGlow = mix(baseColor, uAccent, smoothstep(0.12, 0, gradY).mul(0.18));
  const grain = fract(sin(dot(uv().mul(150), vec2(12.9898, 78.233))).mul(43758.5453));
  const finalColor = accentGlow.add(grain.mul(0.025));

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = finalColor;
  backdropMat.side = DoubleSide;
  disposables.push(backdropMat);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.5;
  inner.add(backdrop);

  // --- Image plane (feature-card texture) ---
  const imageGeo = new PlaneGeometry(4.2, 2.625);
  disposables.push(imageGeo);
  const imageMat = new MeshBasicNodeMaterial();
  imageMat.transparent = true;
  disposables.push(imageMat);

  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, 0.15, 0);
  inner.add(imageMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    imageMat.colorNode = texture(tex);
    imageMat.needsUpdate = true;
  });

  // --- Accent bar ---
  const accentGeo = new PlaneGeometry(0.9, 0.05);
  disposables.push(accentGeo);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = uAccent;
  disposables.push(accentMat);
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -1.25, 0.1);
  inner.add(accentBar);

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 31;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: fontSize,
      color: paperHex,
      align: 'center',
      maxWidthPx: 520,
      letterSpacingPx: 0.5,
    });
    textObj.position.set(0, -1.0, 0.2);
    inner.add(textObj);
  }

  // --- Entrance animation (weighted settle) ---
  inner.scale.set(0.97, 0.97, 1);
  const tl = gsap.timeline();
  tl.to(inner.scale, { x: 1, y: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tl.from(inner.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(accentBar.scale, { x: 0, duration: 0.6, ease: 'power2.out' }, 0.2);
  timelines.push(tl);

  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    disposables.forEach(d => { if (d && d.dispose) d.dispose(); });
  };

  return group;
}
